\section{Notations}\label{sec:notation}

% With the arising of powerful large language models (LLM) and foundation models with transformer neural network architectures, ICL has becomes a new paradigm, where the pre-trained neural network can make predictions based on contexts augmented with a few examples \cite{dong2022survey}.

To mathematically define ICL, 
instead of merely passing a query $x_{q} \in \mathbb{R}^d$ (or a test sample) to the transformer to make a prediction, ICL passes a prompt, i.e., a few examples with their labels $\{(x_i,y_i)\}_{i=1,\ldots,D}$ together with the query $x_{q}$, to the transformer. Using the prompt in the format of
\vspace{-0.1in}
\begin{equation}\label{eqn:input}
  E=\begin{pmatrix}
    x_1 & x_2 & \ldots & x_D & x_{q}\\
    y_1 & y_2 & \ldots & y_D & 0
\end{pmatrix}\in\mathbb{R}^{(d+1) \times (D+1)},  
\end{equation}
the transformer can learn from the examples to infer the prediction for $x_{q}$. Following \citet{zhang2023trained}, we consider the following simplified neural network architecture
\begin{equation}
    f(E)= E+W_{out} H,
\end{equation}
where $H$ denotes the attention node and $W_{out}$ represents a fully-connected layer. Here, 
% The output of the attention node is $W_{out}H$, where

\end{equation}
where $H$ denotes the attention node and $W_{out}$ represents a fully-connected layer. Here, 
% The output of the attention node is $W_{out}H$, where 
$H=\text{concat}(H_1,\ldots, H_h)$, with $h$ being the number of heads in the multi-head attention. Each attention head $H_j$ is given by
\begin{equation}\label{eqn:multi_head}
    H_j = W^V_jE\cdot \phi\left(\frac{(W^K_jE)^{\top}W^Q_jE}{\rho_j} \right)
\end{equation}
where $\rho_j$ is a normalization factor, and the activation function $\phi$ is the column-wise softmax function. For each $j$, $W^V_j, W^K_j, W^Q_j\in\mathbb{R}^{m\times d}$, and $m=d/h$. When $h=1$, the attention is \textbf{single-head}. When $h>1$, the structure is called \textbf{multi-head} attention.

% Formally, let $\mathcal{D}_{\mathcal{X}}$ be a distribution over inputs and $\mathcal{D}_{\mathcal{F}}$ be a distribution over functions in $\mathcal{F}$.
% A prompt $P$ is a sequence $(x_{1}, f(x_{1}), \dots, x_{D}, f(x_{D}), x_{q} )$ where inputs (i.e., $x_{i}$ and $x_{q}$) are drawn i.i.d. from $\mathcal{D}_{\mathcal{X}}$ and $f$ is drawn from $\mathcal{D}_{\mathcal{F}}$. 

% Now we are ready to define in-context learning. 

To train the model, we fetch the last element of the last row in $f(E)$ as the predicted value of $y_q$ (denote as $\widehat{y}_q$), then minimize
\begin{eqnarray}\label{eqn:loss}
    L(\Omega)=\mathbb{E}_{\{x_i\},x_q,\theta}(\widehat y_q-y_q)^2,
\end{eqnarray}
where $\Omega$ is the set of parameters.

