\subsection{Multi-Head Attention is Better}\label{sec:multi_head}
While Section \ref{sec:single_head} shows the effectiveness of single-head attention, in this subsection, through deriving the exact performance, we show that multi-head attention is better than single-head attention.

We consider a two-head attention in the following theorem to illustrate the superiority:

% \begin{theorem}
%     Consider the following transformer: for some positive constants $v,a,b$,

% \end{theorem}
\begin{theorem}[Multi-head Attention is Better]\label{thm:multi_head}
    Consider a two-head attention with
    \begin{eqnarray*}
        (W^K_1)^{\top}W^Q_1 = \begin{bmatrix}
        A_1 & 0 \\ b_1 & 0
        \end{bmatrix},\;(W^K_2)^{\top}W^Q_2 = \begin{bmatrix}
        A_2 & 0 \\ b_2 & 0
        \end{bmatrix}.
    \end{eqnarray*}
    The parameters $W^V_1$, $W^V_2$, $W_{in}$ and $W_{out}$ satisfy
        \begin{eqnarray*}
        f(E)_{d+1,D+1}&=& vm E_{d+1,:}\phi((W_1^KE)^{\top}W_1^QE_{:,D+1})\\
        &&-vn E_{d+1,:}\phi((W_2^KE)^{\top}W_2^QE_{:,D+1}).
    \end{eqnarray*}
    Then the optimal solution satisfies
    that $\|vmA_1-vnA_2\|^2_F=O(1/D)$ and $\|mb_1-nb_2\|^2=O(1/D)$.

&&+\frac{v^2}{D}\left(\frac{v^2}{v^2-2(2c-1)^2}\right)^{\frac{d}{2}} \\ &&+  \frac{(2c-1)^2}{D}\left(\frac{v^2}{v^2-2(2c-1)^2}\right)\left(\frac{v^2}{v^2-2(2c-1)^2}\right)^{\frac{d}{2}} \\
    &&-\frac{(8c-4)c}{D}  \left(\frac{v^2}{v^2-2c(2c-1)}\right)\left(\frac{v^2}{v^2-2c(2c-1)}\right)^{\frac{d}{2}}\\
  &&+  \frac{4c^2}{D}  \left(\frac{v^2}{v^2-2c^2}\right)  \left(\frac{v^2}{v^2-2c^2}\right)^{\frac{d}{2}}+o\left(1/D\right).
    \end{eqnarray*}
    \vspace{-0.2in}
    % which is less than the minimal loss of single-head attention in equation (\ref{eqn:single_optimal}) in Theorem \ref{thm:optimal}.
    % \pf{It is better to emphasize this sentence.}. 
\end{theorem}

In addition to the formula in Theorem \ref{thm:multi_head}, the following proposition illustrates why the loss of multi-head attention is smaller than the optimal loss of single-head attention:
\begin{proposition}\label{prop:multi}
Following the setting of Theorem~\ref{thm:optimal} and \ref{thm:multi_head}, multi-head attention can be reduced to single-head attention when taking $c=1$, and $c=1$ is not the optimal choice for multi-head attention to achieve the minimal loss.  
\end{proposition}
